//! Pre-rendered sprites of the winter visitors: the sleigh, its reindeer,
//! the snowplough and its wheel, the penguin, the fox, the owl and its
//! present. They are modelled and rendered in Blender by
//! `art/visitors/build.py`, which writes the atlas and `table.rs`.

// Generated: not every constant is used.
#[allow(dead_code)]
// Generated by art/visitors/build.py, so rustfmt leaves it as written.
#[rustfmt::skip]
mod table;

pub(crate) use table::*;
pub use table::{ATLAS_HEIGHT, ATLAS_WIDTH, FRAMES, SCALE, anchor};

/// Instances with a shape at or above this draw atlas frame `shape - SHAPE_SPRITE`.
pub const SHAPE_SPRITE: f32 = 32.0;
/// Room in the renderer's frame table.
pub const MAX_SPRITES: usize = 64;
/// Mip levels kept for the atlas, including the full-size one. Atlas cells
/// are padded so that this many levels never bleed into each other.
pub const MIP_LEVELS: u32 = 4;

const ATLAS_PNG: &[u8] = include_bytes!("../../assets/visitors.png");

const _: () = assert!(FRAMES.len() <= MAX_SPRITES);

#[derive(Clone, Copy, Debug)]
pub struct Frame {
    /// x, y, width and height in atlas pixels.
    pub rect: [u32; 4],
    /// The model's origin inside the frame, in atlas pixels.
    pub pivot: [f32; 2],
}

impl Frame {
    /// Drawn size in pixels at scale 1.
    pub fn size(&self) -> [f32; 2] {
        [self.rect[2] as f32 / SCALE, self.rect[3] as f32 / SCALE]
    }
}

/// Each frame's rectangle as normalized atlas coordinates (x, y, w, h).
pub fn uv_rects() -> [[f32; 4]; MAX_SPRITES] {
    let mut out = [[0.0; 4]; MAX_SPRITES];
    let (w, h) = (ATLAS_WIDTH as f32, ATLAS_HEIGHT as f32);
    for (o, f) in out.iter_mut().zip(FRAMES.iter()) {
        let [x, y, fw, fh] = f.rect.map(|v| v as f32);
        *o = [x / w, y / h, fw / w, fh / h];
    }
    out
}

/// One mip level of the atlas: premultiplied RGBA, 8 bits per channel.
pub struct AtlasLevel {
    pub width: u32,
    pub height: u32,
    pub pixels: Vec<u8>,
}

/// Decodes the atlas and builds its mip chain. Colours are premultiplied
/// before filtering, so edges never pick up dark fringes.
pub fn atlas_levels() -> Result<Vec<AtlasLevel>, String> {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(ATLAS_PNG));
    decoder.set_transformations(png::Transformations::EXPAND | png::Transformations::STRIP_16);
    let mut reader = decoder.read_info().map_err(|e| e.to_string())?;
    let size = reader
        .output_buffer_size()
        .ok_or("the sprite atlas is too large")?;
    let mut buf = vec![0; size];
    let info = reader.next_frame(&mut buf).map_err(|e| e.to_string())?;
    let (width, height) = (info.width, info.height);
    if (width, height) != (ATLAS_WIDTH, ATLAS_HEIGHT) {
        return Err(format!(
            "the sprite atlas is {width}x{height}, but its table expects {ATLAS_WIDTH}x{ATLAS_HEIGHT}"
        ));
    }
    let channels = match info.color_type {
        png::ColorType::Rgba => 4,
        png::ColorType::Rgb => 3,
        png::ColorType::GrayscaleAlpha => 2,
        png::ColorType::Grayscale => 1,
        png::ColorType::Indexed => return Err("unexpected indexed atlas".into()),
    };
    let mut pixels = Vec::with_capacity((width * height * 4) as usize);
    for px in buf[..info.buffer_size()].chunks_exact(channels) {
        let (rgb, a) = match channels {
            4 => ([px[0], px[1], px[2]], px[3]),
            3 => ([px[0], px[1], px[2]], 255),
            2 => ([px[0]; 3], px[1]),
            _ => ([px[0]; 3], 255),
        };
        let k = a as u32;
        pixels.extend(rgb.map(|c| ((c as u32 * k + 127) / 255) as u8));
        pixels.push(a);
    }
    let mut levels = vec![AtlasLevel {
        width,
        height,
        pixels,
    }];
    for _ in 1..MIP_LEVELS {
        let prev = levels.last().unwrap();
        let (w, h) = ((prev.width / 2).max(1), (prev.height / 2).max(1));
        let mut next = Vec::with_capacity((w * h * 4) as usize);
        for y in 0..h {
            for x in 0..w {
                for c in 0..4 {
                    let at = |dx: u32, dy: u32| {
                        let (sx, sy) = (
                            (x * 2 + dx).min(prev.width - 1),
                            (y * 2 + dy).min(prev.height - 1),
                        );
                        prev.pixels[((sy * prev.width + sx) * 4 + c) as usize] as u32
                    };
                    next.push(((at(0, 0) + at(1, 0) + at(0, 1) + at(1, 1) + 2) / 4) as u8);
                }
            }
        }
        levels.push(AtlasLevel {
            width: w,
            height: h,
            pixels: next,
        });
    }
    Ok(levels)
}
